441	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
442	        return Collections.unmodifiableList(sortedPets);
443	    }
444	
445	    public void setPets(List<Pet> pets) {
446	        this.pets = new HashSet<>(pets);
447	    }
448	
449	    public void addPet(Pet pet) {
450	        getPetsInternal().add(pet);
451	        pet.setOwner(this);
452	    }
453	
454	    /**
455	     * Return the Pet with the given name, or null if none found for this Owner.
456	     *
457	     * @param name to test
458	     * @return true if pet name is already in use
459	     */
460	    public Pet getPet(String name) {
461	        return getPet(name, false);
462	    }
463	
464	    /**
465	     * Return the Pet with the given name, or null if none found for this Owner.
466	     *
467	     * @param name to test
468	     * @return true if pet name is already in use
469	     */
470	    public Pet getPet(String name, boolean ignoreNew) {
471	        name = name.toLowerCase();
472	        for (Pet pet : getPetsInternal()) {
473	            if (!ignoreNew || !pet.isNew()) {
474	                String compName = pet.getName();
475	                compName = compName.toLowerCase();
476	                if (compName.equals(name)) {
477	                    return pet;
478	                }
479	            }
480	        }
481	        return null;
482	    }
483	
484	    public Pet getPet(Integer petId) {
485	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
486	    }
487	
488	    @Override
489	    public String toString() {
490	        return new ToStringCreator(this)
491	
492	            .append("id", this.getId())
493	            .append("new", this.isNew())
494	            .append("lastName", this.getLastName())
495	            .append("firstName", this.getFirstName())
496	            .append("address", this.address)
497	            .append("city", this.city)
498	            .append("telephone", this.telephone)
499	            .toString();
500	    }
501	}
